using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<Person> directly (no cast needed)
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    Person is resolvable, so this succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

//    Use a resolver that only knows about Person, so Widget will NOT resolve:
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            ti =>
            {
                if (ti.Type != typeof(Person))
                    throw new NotSupportedException($"Not supported: {ti.Type.Name}");
            }
        }
    }
};
// Force options to be read-only (required before querying type info)
limited.MakeReadOnly();

if (limited.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Widget> succeeded (unexpected)");
}
else
{
    Console.WriteLine($"\nTryGetTypeInfo<Widget> returned false — no exception thrown.");
}

// Types used in this demo
public record Person(string Name, int Age);
public record Widget(int Id, string Label);
EOF

